from flask import Flask, redirect, url_for, session, request
from msal import ConfidentialClientApplication
import uuid

app = Flask(__name__)
app.secret_key = 'your_secret_key_here'  # Replace with a secure random key

CLIENT_ID = 'your_client_id_here'
CLIENT_SECRET = 'your_client_secret_here'
TENANT_ID = 'your_tenant_id_here'
AUTHORITY = f'https://login.microsoftonline.com/{TENANT_ID}'
REDIRECT_PATH = '/getAToken'

SCOPE = ['User.Read']

msal_app = ConfidentialClientApplication(
    CLIENT_ID, authority=AUTHORITY,
    client_credential=CLIENT_SECRET
)

@app.route('/')
def index():
    if 'user' in session:
        return f"Hello, {session['user']['name']}! <a href='/logout'>Logout</a>"
    else:
        return "<a href='/login'>Login with Microsoft Entra ID</a>"

@app.route('/login')
def login():
    # Generate a random state to protect against CSRF
    session['state'] = str(uuid.uuid4())
    auth_url = msal_app.get_authorization_request_url(
        scopes=SCOPE,
        state=session['state'],
        redirect_uri=url_for('authorized', _external=True)
    )
    print(f"Redirecting user to login URL: {auth_url}")
    return redirect(auth_url)

@app.route(REDIRECT_PATH)
def authorized():
    # Check state parameter to prevent CSRF
    if request.args.get('state') != session.get('state'):
        return "State mismatch. Possible CSRF attack.", 400

    if 'error' in request.args:
        return f"Error: {request.args['error_description']}", 400

    code = request.args.get('code')
    if not code:
        return "No code found in request.", 400

    # Acquire token by authorization code
    result = msal_app.acquire_token_by_authorization_code(
        code,
        scopes=SCOPE,
        redirect_uri=url_for('authorized', _external=True)
    )

    if 'access_token' in result:
        # Save user info in session
        session['user'] = result.get('id_token_claims')
        print(f"User {session['user']['name']} logged in successfully.")
        return redirect(url_for('index'))
    else:
        error = result.get('error')
        error_desc = result.get('error_description')
        print(f"Token acquisition failed: {error} - {error_desc}")
        return f"Login failed: {error_desc}", 400

@app.route('/logout')
def logout():
    session.clear()
    return redirect(
        f'https://login.microsoftonline.com/common/oauth2/v2.0/logout?post_logout_redirect_uri={url_for("index", _external=True)}'
    )

if __name__ == '__main__':
    print('Starting Flask app for Microsoft Entra ID authentication demo...')
    app.run(debug=True)
